fn fetch_receipt(source: &Path, receiver: &Path, module: &str, auth_key: &Path) -> String {
    let address = unused_address();
    let server = peer::spawn_server(source, &address, module, super::NODE, auth_key);
    let fetched = peer::fetch(receiver, &address, module, super::NODE, auth_key);
    assert!(server.wait_with_output().unwrap().status.success());
    fetched["authenticated_provision_receipt_cid"]
        .as_str()
        .unwrap()
        .to_owned()
}

fn export_root(cwd: &Path, root: &str, bundle: &Path) {
    let exported = run_json(
        cwd,
        [
            OsString::from("object"),
            OsString::from("bundle"),
            OsString::from("export"),
            OsString::from(root),
            OsString::from("--out"),
            bundle.as_os_str().to_owned(),
            OsString::from("--format"),
            OsString::from("json"),
        ],
    );
    assert_eq!(exported["root_cids"], json!([root]));
}

fn unused_address() -> String {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    listener.local_addr().unwrap().to_string()
}

