/// Verifies sequence continuity, previous-event links, and recomputed event CIDs.
pub fn verify_chain(events: &[DagEvent]) -> Result<()> {
    let mut previous = None;
    for (index, event) in events.iter().enumerate() {
        if event.sequence != index as u64 {
            bail!(
                "event sequence mismatch at index {index}: expected {}, got {}",
                index,
                event.sequence
            );
        }
        if event.previous_event_cid != previous {
            bail!("event previous link mismatch at index {index}");
        }
        let expected = event_cid(event)?;
        if event.event_cid != expected {
            bail!("event cid mismatch at index {index}");
        }
        previous = Some(event.event_cid.clone());
    }
    Ok(())
}

