using UnityEngine;

[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class HemisphereGenerator : MonoBehaviour
{
    public float radius = 5f;
    public int segments = 32;
    public int rings = 16;

    void Start()
    {
        Mesh mesh = new Mesh();
        Vector3[] vertices = new Vector3[(segments + 1) * (rings + 1)];
        int[] triangles = new int[segments * rings * 6];
        Vector2[] uv = new Vector2[vertices.Length];

        // Generate vertices and UVs
        for (int ring = 0; ring <= rings; ring++)
        {
            float theta = Mathf.PI / 2 * ring / rings; // 0 to 90 degrees
            for (int seg = 0; seg <= segments; seg++)
            {
                float phi = 2 * Mathf.PI * seg / segments;
                float x = radius * Mathf.Sin(theta) * Mathf.Cos(phi);
                float y = radius * Mathf.Cos(theta);
                float z = radius * Mathf.Sin(theta) * Mathf.Sin(phi);
                vertices[ring * (segments + 1) + seg] = new Vector3(x, y, z);

                // UV mapping
                uv[ring * (segments + 1) + seg] = new Vector2((float)seg / segments, (float)ring / rings);
            }
        }

        // Generate triangles
        int ti = 0;
        for (int ring = 0; ring < rings; ring++)
        {
            for (int seg = 0; seg < segments; seg++)
            {
                int current = ring * (segments + 1) + seg;
                int next = (ring + 1) * (segments + 1) + seg;

                triangles[ti++] = current;
                triangles[ti++] = next;
                triangles[ti++] = current + 1;

                triangles[ti++] = current + 1;
                triangles[ti++] = next;
                triangles[ti++] = next + 1;
            }
        }

        mesh.vertices = vertices;
        mesh.triangles = triangles;
        mesh.uv = uv;
        mesh.RecalculateNormals();

        GetComponent<MeshFilter>().mesh = mesh;
    }
}
