### **LensDistortionController.cs**

```csharp
using UnityEngine;

public class LensDistortionController : MonoBehaviour
{
    public Material leftDistortionMaterial;
    public Material rightDistortionMaterial;

    [Range(-1f, 1f)] public float K1 = 0.1f;
    [Range(-1f, 1f)] public float K2 = 0.05f;
    public Vector2 center = new Vector2(0.5f, 0.5f);

    void Update()
    {
        if (leftDistortionMaterial != null && rightDistortionMaterial != null)
        {
            leftDistortionMaterial.SetFloat("_K1", K1);
            leftDistortionMaterial.SetFloat("_K2", K2);
            leftDistortionMaterial.SetVector("_Center", new Vector4(center.x * 0.5f, center.y, 0, 0)); // 左半边中心

            rightDistortionMaterial.SetFloat("_K1", K1);
            rightDistortionMaterial.SetFloat("_K2", K2);
            rightDistortionMaterial.SetVector("_Center", new Vector4(center.x * 0.5f + 0.5f, center.y, 0, 0)); // 右半边中心
        }
    }
}
